import { Component, createMemo, Index } from "solid-js";

import { L10n } from "#core/ui-next/components/l10n.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

interface TreasureConvoyProgressBarProps {
	segmentCount: number;
	currentValue: number;
}
const TreasureConvoyProgressBarComponent: Component<TreasureConvoyProgressBarProps> = (props) => {
	const items = createMemo(() => Array.from({ length: props.segmentCount }, (_, i) => i));

	return (
		<div class="w-full flex flex-col">
			<div class="w-full flex flex-row text-secondary">
				<div class="grow">
					<L10n.Compose text="LOC_COMMERCE_TREASURE_FLEET_LOADING" />
				</div>
				<L10n.Compose
					text="LOC_COMMERCE_TREASURE_FLEET_PROGRESS"
					args={[props.currentValue, props.segmentCount]}
				/>
			</div>
			<div
				class="w-full h-4 flex flex-row p-1 mt-2"
				style={{ "background-color": "rgba(0, 0, 0, 0.4)", border: "solid 2px rgba(64, 68, 83, 1)" }}
			>
				<Index each={items()}>
					{(_, i) => (
						<div
							class="flex-auto h-full"
							classList={{ "mr-1": i < items().length - 1 }}
							style={{
								"background-color":
									i >= props.currentValue ? "rgba(58, 115, 65, 0.2)" : "rgba(58, 115, 65, 1)",
							}}
						/>
					)}
				</Index>
			</div>
		</div>
	);
};

export const TreasureConvoyProgressBar = ComponentRegistry.register({
	name: "TreasureConvoyProgressBar",
	createInstance: TreasureConvoyProgressBarComponent,
});
